func (s *Server) groupUpdate(w http.ResponseWriter,r *http.Request){var in struct{GroupID,UserID,Name,Username,AvatarBase64,AvatarMimeType string};if decode(r,&in)!=nil||in.GroupID==""||in.UserID==""{groupBad(w,"缺少必要参数");return};ok,e:=groupRequireRole(r.Context(),s,in.GroupID,in.UserID,"owner","admin");if e!=nil||!ok{writeJSON(w,403,map[string]string{"error":"仅群主和管理员可修改群信息"});return};updates:=[]string{};args:=[]any{in.GroupID};if in.Name!=""{name:=strings.TrimSpace(in.Name);if name==""||len(name)>30{groupBad(w,"群名称不能为空或超过30个字符");return};args=append(args,name);updates=append(updates,fmt.Sprintf(`"name"=$%d`,len(args)))};if in.Username!=""{if !groupUsernameRE.MatchString(in.Username){groupBad(w,"群 ID 必须以字母开头，5-32位字母数字下划线");return};args=append(args,in.Username);updates=append(updates,fmt.Sprintf(`"username"=$%d,"isPublic"=true`,len(args)))};if len(updates)==0{groupBad(w,"没有需要修改的内容");return};q:=`UPDATE "Group" SET `+strings.Join(updates,",")+`,"updatedAt"=NOW() WHERE "id"=$1`;if _,e=s.db.Exec(r.Context(),q,args...);e!=nil{dbError(w,e);return};var id,name string;var av,un *string;var pub bool;_=s.db.QueryRow(r.Context(),`SELECT "id","name","avatar","username","isPublic" FROM "Group" WHERE "id"=$1`,in.GroupID).Scan(&id,&name,&av,&un,&pub);writeJSON(w,200,map[string]any{"ok":true,"group":map[string]any{"id":id,"name":name,"avatar":av,"username":un,"isPublic":pub}})}

