func (s *Server) groupMute(w http.ResponseWriter,r *http.Request){var in struct{GroupID,OperatorID,TargetUserID string;Duration int64};if decode(r,&in)!=nil||in.GroupID==""||in.OperatorID==""||in.TargetUserID==""{groupBad(w,"缺少必要参数");return};role,e:=groupRole(r.Context(),s,in.GroupID,in.OperatorID);if e!=nil||role!="owner"&&role!="admin"{writeJSON(w,403,map[string]string{"error":"仅群主和管理员可以禁言"});return};tr,e:=groupRole(r.Context(),s,in.GroupID,in.TargetUserID);if e!=nil{writeJSON(w,404,map[string]string{"error":"目标用户不是群成员"});return};if tr=="owner"||(tr=="admin"&&role!="owner"){writeJSON(w,403,map[string]string{"error":"不能禁言该成员"});return};var until any;if in.Duration>0{until=time.Now().Add(time.Duration(in.Duration)*time.Second)};_,e=s.db.Exec(r.Context(),`UPDATE "GroupMember" SET "muteUntil"=$3,"updatedAt"=NOW() WHERE "groupId"=$1 AND "userId"=$2`,in.GroupID,in.TargetUserID,until);if e!=nil{dbError(w,e);return};writeJSON(w,200,map[string]any{"ok":true,"muteUntil":until})}
