func (s *Server) groupInviteMembers(w http.ResponseWriter,r *http.Request){var in struct{GroupID,InviterID string;MemberIDs []string `json:"memberIds"`};if decode(r,&in)!=nil||in.GroupID==""||in.InviterID==""{groupBad(w,"缺少必要参数");return};if len(in.MemberIDs)>50{groupBad(w,"一次最多邀请50人");return};if _,e:=groupRole(r.Context(),s,in.GroupID,in.InviterID);e!=nil{writeJSON(w,403,map[string]string{"error":"非群成员"});return};invited:=[]string{};alreadyMembers:=[]string{};alreadyPending:=[]string{};for _,uid:=range in.MemberIDs{var member,pending bool;_=s.db.QueryRow(r.Context(),`SELECT EXISTS(SELECT 1 FROM "GroupMember" WHERE "groupId"=$1 AND "userId"=$2),EXISTS(SELECT 1 FROM "GroupInvite" WHERE "groupId"=$1 AND "inviteeId"=$2 AND "status"='pending')`,in.GroupID,uid).Scan(&member,&pending);if member{alreadyMembers=append(alreadyMembers,uid);continue};if pending{alreadyPending=append(alreadyPending,uid);continue};if _,e:=s.db.Exec(r.Context(),`INSERT INTO "GroupInvite" ("id","groupId","inviterId","inviteeId","message","status","createdAt","updatedAt") VALUES ($1,$2,$3,$4,'','pending',NOW(),NOW())`,newID(),in.GroupID,in.InviterID,uid);e==nil{invited=append(invited,uid)}};var name string;_=s.db.QueryRow(r.Context(),`SELECT "name" FROM "Group" WHERE "id"=$1`,in.GroupID).Scan(&name);writeJSON(w,200,map[string]any{"ok":true,"invited":invited,"alreadyPending":alreadyPending,"alreadyMembers":alreadyMembers,"groupName":name})}
func (s *Server) groupInvites(w http.ResponseWriter,r *http.Request){uid:=groupQuery(r,"userId");if uid==""{groupBad(w,"缺少 userId");return};typ:=groupQuery(r,"type");if typ==""{typ="received"};clause:=`gi."inviteeId"=$1`;if typ=="sent"{clause=`gi."inviterId"=$1`}else if typ=="all"{clause=`(gi."inviteeId"=$1 OR gi."inviterId"=$1)`};rows,e:=s.db.Query(r.Context(),`SELECT gi."id",gi."groupId",g."name",g."avatar",g."memberCount",gi."inviterId",COALESCE(i."nickname",i."username",gi."inviterId"),COALESCE(i."avatar",''),gi."inviteeId",COALESCE(eu."nickname",eu."username",gi."inviteeId"),COALESCE(eu."avatar",''),gi."message",gi."status",gi."createdAt" FROM "GroupInvite" gi JOIN "Group" g ON g."id"=gi."groupId" LEFT JOIN "User" i ON i."id"=gi."inviterId" LEFT JOIN "User" eu ON eu."id"=gi."inviteeId" WHERE `+clause+` ORDER BY gi."createdAt" DESC`,uid);if e!=nil{dbError(w,e);return};defer rows.Close();out:=[]map[string]any{};for rows.Next(){var id,gid,gname,inviterName,inviteeName,msg,status string;var gav,iav,eav *string;var count int64;var inviter,invitee string;var t time.Time;if rows.Scan(&id,&gid,&gname,&gav,&count,&inviter,&inviterName,&iav,&invitee,&inviteeName,&eav,&msg,&status,&t)!=nil{continue};out=append(out,map[string]any{"id":id,"groupId":gid,"groupName":gname,"groupAvatar":gav,"groupMemberCount":count,"inviterId":inviter,"inviterName":inviterName,"inviterAvatar":iav,"inviteeId":invitee,"inviteeName":inviteeName,"inviteeAvatar":eav,"message":msg,"status":status,"timestamp":t,"isIncoming":invitee==uid})};writeJSON(w,200,map[string]any{"invites":out})}
func (s *Server) groupInviteAccept(w http.ResponseWriter,r *http.Request){id:=r.PathValue("inviteId");var in struct{UserID string};if decode(r,&in)!=nil||id==""||in.UserID==""{groupBad(w,"缺少 userId");return};var gid,invitee,status,gname string;var avatar *string;e:=s.db.QueryRow(r.Context(),`SELECT gi."groupId",gi."inviteeId",gi."status",g."name",g."avatar" FROM "GroupInvite" gi JOIN "Group" g ON g."id"=gi."groupId" WHERE gi."id"=$1`,id).Scan(&gid,&invitee,&status,&gname,&avatar);if e!=nil{writeJSON(w,404,map[string]string{"error":"群邀请不存在"});return};if invitee!=in.UserID||status!="pending"{writeJSON(w,403,map[string]string{"error":"无权处理该邀请"});return};var seq int64;_=s.db.QueryRow(r.Context(),`SELECT "lastMsgSeq" FROM "Group" WHERE "id"=$1`,gid).Scan(&seq);if _,e=s.db.Exec(r.Context(),`UPDATE "GroupInvite" SET "status"='accepted',"updatedAt"=NOW() WHERE "id"=$1`,id);e!=nil{dbError(w,e);return};if _,e=s.db.Exec(r.Context(),`INSERT INTO "GroupMember" ("id","groupId","userId","lastAckSeq","joinTime","createdAt","updatedAt") VALUES ($1,$2,$3,$4,NOW(),NOW(),NOW()) ON CONFLICT ("groupId","userId") DO NOTHING`,newID(),gid,in.UserID,seq);e!=nil{dbError(w,e);return};_,_=s.db.Exec(r.Context(),`UPDATE "Group" SET "memberCount"="memberCount"+1 WHERE "id"=$1`,gid);writeJSON(w,200,map[string]any{"ok":true,"message":"已加入群聊","groupId":gid,"groupName":gname,"groupAvatar":avatar})}
func (s *Server) groupInviteReject(w http.ResponseWriter,r *http.Request){id:=r.PathValue("inviteId");var in struct{UserID string};if decode(r,&in)!=nil||id==""||in.UserID==""{groupBad(w,"缺少 userId");return};var invitee,status string;e:=s.db.QueryRow(r.Context(),`SELECT "inviteeId","status" FROM "GroupInvite" WHERE "id"=$1`,id).Scan(&invitee,&status);if e!=nil{writeJSON(w,404,map[string]string{"error":"群邀请不存在"});return};if invitee!=in.UserID||status!="pending"{writeJSON(w,403,map[string]string{"error":"无权处理该邀请"});return};_,e=s.db.Exec(r.Context(),`UPDATE "GroupInvite" SET "status"='rejected',"updatedAt"=NOW() WHERE "id"=$1`,id);if e!=nil{dbError(w,e);return};writeJSON(w,200,map[string]any{"ok":true,"message":"已拒绝群邀请"})}
func (s *Server) groupBurnMessage(w http.ResponseWriter,r *http.Request){var in struct{MessageID,ChatID string};if decode(r,&in)!=nil||in.MessageID==""{groupBad(w,"缺少 messageId");return};_,e:=s.db.Exec(r.Context(),`UPDATE "GroupMessage" SET "isRevoked"=true,"content"='[消息已销毁]',"extra"=NULL WHERE "id"=$1`,in.MessageID);if e!=nil{dbError(w,e);return};writeJSON(w,200,map[string]bool{"ok":true})}
